      "Industrial_and_Scientific:pos_neg_neg_beats_pos_rate": 0.0268,
      "Electronics:embedding_collapse_score": 0.6195
    },
    "brief_metric_read": {
      "padding_feature_max_abs_error": "All categories substantially exceed the declared tolerance.",
      "pos_neg_neg_beats_pos_rate": "Movies has the highest sampled training error rate; Industrial has the lowest.",
      "embedding_collapse_score": "Electronics has the strongest mean directional alignment; this does not measure recommendation diversity."
    }
  }
}
